<template><Layout><div class="flow-page"><div class="flow-header"><Button text icon="mdi mdi-arrow-left" @click="router.push('/dashboard')" /><div><div class="eyebrow">Release flow</div><h1>{{ flow?.name || 'Release flow' }}</h1><p>{{ flow?.description || 'Configure and ship this release.' }}</p></div><Button label="Ship" icon="mdi mdi-rocket-launch-outline" :disabled="!flow" @click="ship" /></div><Message v-if="!flow" severity="warn">This release flow could not be loaded.</Message><template v-else><div class="source-card"><i class="mdi mdi-source-branch"></i><div><strong>{{ flow.source.type === 'construct3' ? 'Construct 3 project' : 'Built folder' }}</strong><span>{{ flow.source.path }}</span></div><Button label="Configure" text @click="showAdvanced = true" /></div><h2>Destinations</h2><div class="destinations"><div v-for="dest in flow.destinations" :key="dest.type" class="destination"><i class="mdi" :class="dest.type === 'steam' ? 'mdi-steam' : dest.type === 'itch' ? 'mdi-puzzle-outline' : 'mdi-web'"></i><div><strong>{{ dest.type === 'steam' ? 'Steam' : dest.type === 'itch' ? 'Itch.io' : 'Web folder' }}</strong><span>{{ destinationSummary(dest) }}</span></div><Tag value="Ready" severity="success" /></div></div><Button label="Add destination" icon="mdi mdi-plus" outlined @click="showAdvanced = true" /></template><Dialog v-model:visible="showAdvanced" modal header="Flow configuration" :style="{ width: '560px', maxWidth: '95vw' }"><p>Advanced source, destination, connection, and OS settings are kept here so the main flow stays focused.</p><Button label="Manage connections" outlined @click="router.push('/connections')" /></Dialog></div></Layout></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import Layout from '@renderer/components/Layout.vue'; import Button from 'primevue/button'; import Dialog from 'primevue/dialog'; import Message from 'primevue/message'; import Tag from 'primevue/tag'; import { useAPI } from '@renderer/composables/api'; import type { ReleaseFlow, ReleaseFlowDestination } from '@pipelab/shared';
const route = useRoute(); const router = useRouter(); const api = useAPI(); const flow = ref<ReleaseFlow>(); const showAdvanced = ref(false);
onMounted(async () => { const result = await api.execute('release-flow:load-by-name', { name: `release-flows/${route.params.flowId}` }); if (result.type === 'success') flow.value = result.result as ReleaseFlow; });
const destinationSummary = (dest: ReleaseFlowDestination) => dest.type === 'steam' ? `App ${dest.appId} · ${dest.connectionId || 'Connection required'}` : dest.type === 'itch' ? `${dest.project} · ${dest.channel}` : dest.outputDir;
const ship = () => { /* compiler/runner integration follows the same graph execution pathway */ };
</script>
<style scoped>.flow-page{max-width:820px;margin:0 auto;padding:32px 24px}.flow-header{display:flex;align-items:center;gap:16px;margin-bottom:32px}.flow-header>div{flex:1}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--text-color-secondary)}h1{margin:4px 0;font-size:26px}.flow-header p{margin:0;color:var(--text-color-secondary)}h2{font-size:16px;margin:28px 0 12px}.source-card,.destination{display:flex;align-items:center;gap:14px;padding:16px;border:1px solid var(--surface-border);border-radius:10px;margin-bottom:10px}.source-card i,.destination>i{font-size:24px;color:var(--primary-color)}.source-card div,.destination div{display:flex;flex-direction:column;gap:4px;flex:1}.source-card span,.destination span{font-size:12px;color:var(--text-color-secondary)}.destination strong{font-size:14px}</style>
